// W3C traceparent: version-traceid-parentspanid-flags. Inject on call, extract on receive.
var counter = 0;
function newSpanId() { counter += 1; return ('0000000000000000' + (0xabc000 + counter).toString(16)).slice(-16); }

var traces = 0;
function newTraceId() { traces += 1; return ('00000000000000000000000000000000' + (0x4bf92f35 * 16 + traces).toString(16)).slice(-32); }

function inject(ctx, headers) {
  headers['traceparent'] = '00-' + ctx.traceId + '-' + ctx.spanId + '-' + (ctx.sampled ? '01' : '00');
}

function extract(headers) {
  var p = (headers['traceparent'] || '').split('-');
  if (p.length !== 4 || p[1].length !== 32) return null;     // missing or malformed: start a new trace
  return { traceId: p[1], parentId: p[2], sampled: p[3] === '01' };
}

function startSpan(name, incoming) {
  var parent = incoming ? extract(incoming) : null;
  var traceId = parent ? parent.traceId : newTraceId();   // no header: a brand new trace
  var span = { name: name, traceId: traceId, spanId: newSpanId(), parentId: parent ? parent.parentId : '-', sampled: parent ? parent.sampled : true };
  console.log(name + ': trace=' + '..' + span.traceId.slice(-6) + ' span=' + span.spanId.slice(-6) + ' parent=' + span.parentId.slice(-6));
  return span;
}

var a = startSpan('service-A', null);          // the entry point creates the trace
var headers = {};
inject(a, headers);                            // A writes the header on the outgoing call
console.log('header:', headers.traceparent);
var b = startSpan('service-B', headers);       // B extracts it: same trace id, parent = A
var h2 = {};
inject(b, h2);
startSpan('service-C', h2);
startSpan('lost-hop', {});                     // a hop that forgot the header starts a NEW trace
